export const PACK_XML: Record<string, string> = {
  "first-gate.xml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<area schemaVersion=\"3\" id=\"first-gate\" order=\"4\" title=\"Why Gate\" shortTitle=\"Why\" subtitle=\"Why is there a world at all?\" icon=\"gate\" accent=\"#c46b4a\">\n  <blurb>Aristotle walked this road; Aquinas drew the map; the question has not aged out.</blurb>\n  <intro>The oldest gate in Silver City has no lock — only a line in the stone: Why is there a world at all?</intro>\n  <intro>Cosmological arguments do not begin with a vision. They begin with ordinary facts: things change; things might not have been; this universe appears to have a beginning.</intro>\n  <intro>If the steps hold, you do not yet have the whole creed. You have a destination with a name in classical theism: a first mover, a necessary being, a cause of what begins. Further attributes take further work. That honesty is strength.</intro>\n  <lesson id=\"daily-cosmos\" title=\"Why anything at all\" idea=\"why there is anything at all points to a Source\">\n    <claim>The universe exists and did not have to — so a Source is worth naming.</claim>\n    <plain>The universe exists and did not have to — so a Source is worth naming.</plain>\n    <source>Psalm 8:3–4</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <easy points=\"10\" easyOrder=\"22\">\n      <learn>The world is here, and it did not have to be. The psalms name a Giver — not a shrug.</learn>\n      <match sentence=\"The universe exists and did not have to — so a Source is worth naming.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The psalms ask why — and expect a Giver.</why>\n        <claimMiss>Questions about a source are impolite.</claimMiss>\n        <claimMiss>Existence plus contingency yields no question.</claimMiss>\n        <whyMiss>The universe had to exist just as it is.</whyMiss>\n        <whyMiss>The psalms refuse to look at the heavens.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The psalms ask the question out loud and expect a Giver, not a shrug.</learn>\n      <match sentence=\"The universe exists and did not have to — so a Source is worth naming.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The psalms ask the question out loud and expect a Giver, not a shrug.</why>\n        <claimMiss>Questions about a source are impolite.</claimMiss>\n        <claimMiss>Existence plus contingency yields no question.</claimMiss>\n        <whyMiss>The universe had to exist just as it is.</whyMiss>\n        <whyMiss>The psalms refuse to look at the heavens.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Psalm 8: when I look at your heavens… what is man that you are mindful of him?</learn>\n      <match sentence=\"The universe exists and did not have to — so a Source is worth naming.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>The psalms ask the question out loud and expect a Giver, not a shrug.</why>\n        <claimMiss>Questions about a source are impolite.</claimMiss>\n        <claimMiss>Existence plus contingency yields no question.</claimMiss>\n        <whyMiss>The universe had to exist just as it is.</whyMiss>\n        <whyMiss>The psalms refuse to look at the heavens.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"fg-mover\" title=\"The unmoved mover\" idea=\"change here and now still asks for a first changer\">\n    <claim>Change here and now needs a first actuality that is not itself a receiver of change.</claim>\n    <plain>Change here and now still asks for a first changer.</plain>\n    <source>Aquinas, ST I, q.2, a.3 (First Way)</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <journal title=\"Unmoved mover\" kicker=\"Why Gate\">\n      <body>Aristotle and Aquinas begin with change: the everyday passage from potential to actual. If nothing explains its own becoming, and a stack of unexplained becomings is not an explanation, then there is a first actuality that is not itself a receiver of change.</body>\n      <body>Read “first” as the bottom of the explanation, not merely the earliest date on a calendar. That is why the argument can be aimed at the present cosmos, not only at a first Tuesday.</body>\n      <cite>Aristotle, Physics VIII; Metaphysics XII</cite>\n      <cite>Aquinas, Summa Theologiae I, q.2, a.3 (First Way)</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"23\">\n      <learn>Things go from “can be” to “is.” Nothing gives itself that step. A stack of receivers is not an answer. There is a first changer not itself changed.</learn>\n      <match sentence=\"Change here and now needs a first actuality that is not itself a receiver of change.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Nothing changes itself without a first mover.</why>\n        <claimMiss>This is only a story about dominoes at the Big Bang.</claimMiss>\n        <claimMiss>Each changing thing explains itself.</claimMiss>\n        <whyMiss>“First” here means the earliest date on a calendar.</whyMiss>\n        <whyMiss>Infinite backlog automatically explains present change.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Nothing reduces itself from potential to actual; an unexplained stack of changers is not an explanation.</learn>\n      <match sentence=\"Change here and now needs a first actuality that is not itself a receiver of change.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Nothing reduces itself from potential to actual; an unexplained stack of changers is not an explanation.</why>\n        <claimMiss>This is only a story about dominoes at the Big Bang.</claimMiss>\n        <claimMiss>Each changing thing explains itself.</claimMiss>\n        <whyMiss>“First” here means the earliest date on a calendar.</whyMiss>\n        <whyMiss>Infinite backlog automatically explains present change.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Critics ask whether quantum events or a past-eternal cosmos break the chain. Defenders reply that contingent, changing states still need a cause of their actuality. The argument’s nerve is explanation, not a stopwatch.</learn>\n      <match sentence=\"Change here and now needs a first actuality that is not itself a receiver of change.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>Nothing reduces itself from potential to actual; an unexplained stack of changers is not an explanation.</why>\n        <claimMiss>This is only a story about dominoes at the Big Bang.</claimMiss>\n        <claimMiss>Each changing thing explains itself.</claimMiss>\n        <whyMiss>“First” here means the earliest date on a calendar.</whyMiss>\n        <whyMiss>Infinite backlog automatically explains present change.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"fg-contingent\" title=\"What might not have been\" idea=\"what might not have been needs a ground\">\n    <claim>A world of might-not-have-beens still needs a necessary ground.</claim>\n    <plain>What might not have been needs a ground.</plain>\n    <source>Aquinas’s Third Way; Leibniz on sufficient reason</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <journal title=\"Necessary being\" kicker=\"Why Gate\">\n      <body>Contingent things exist. A world made only of “might-not-have-beens” does not contain the reason why there is anything. Classical theism names the necessary ground God.</body>\n      <body>Rivals relocate necessity into the universe, or they accept a brute fact. Those are intelligible moves. They are not automatically cheaper. “It just is” is also a metaphysics.</body>\n      <cite>Aquinas, ST I, q.2, a.3 (Third Way)</cite>\n      <cite>Leibniz on sufficient reason</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"24\">\n      <learn>You exist, but you might not have. A world of only “might-not-have-beens” does not explain why anything is here. Classical theism names the necessary ground God.</learn>\n      <match sentence=\"A world of might-not-have-beens still needs a necessary ground.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Things that might not exist still need a ground.</why>\n        <claimMiss>Contingent things contain the reason why there is anything.</claimMiss>\n        <claimMiss>Rivals are unintelligible and need not be named.</claimMiss>\n        <whyMiss>Necessary being is only a weather report.</whyMiss>\n        <whyMiss>Brute fact is not a metaphysical move.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Contingent things exist; “it just is” is also a metaphysics, not automatically cheaper.</learn>\n      <match sentence=\"A world of might-not-have-beens still needs a necessary ground.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Contingent things exist; “it just is” is also a metaphysics, not automatically cheaper.</why>\n        <claimMiss>Contingent things contain the reason why there is anything.</claimMiss>\n        <claimMiss>Rivals are unintelligible and need not be named.</claimMiss>\n        <whyMiss>Necessary being is only a weather report.</whyMiss>\n        <whyMiss>Brute fact is not a metaphysical move.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Atheist replies include: the universe itself is necessary; or “brute fact” is acceptable; or quantum vacua suffice. Each reply relocates necessity or else gives up explanation. That is a real debate — not a slogan fight.</learn>\n      <match sentence=\"A world of might-not-have-beens still needs a necessary ground.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>Contingent things exist; “it just is” is also a metaphysics, not automatically cheaper.</why>\n        <claimMiss>Contingent things contain the reason why there is anything.</claimMiss>\n        <claimMiss>Rivals are unintelligible and need not be named.</claimMiss>\n        <whyMiss>Necessary being is only a weather report.</whyMiss>\n        <whyMiss>Brute fact is not a metaphysical move.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"fg-kalam\" title=\"Whatever begins\" idea=\"whatever begins still asks for a cause\">\n    <claim>If what begins has a cause and the universe began, it has a cause.</claim>\n    <plain>Whatever begins still asks for a cause.</plain>\n    <source>Kalām tradition; contemporary analytic statements</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <journal title=\"Beginning and cause\" kicker=\"Why Gate\">\n      <body>The kalām form is clean: what begins has a cause; the universe began; therefore it has a cause. The second premise is argued from the impossibility of an infinite past and from the cosmos we actually observe.</body>\n      <body>That yields a cause of the beginning. Personhood, goodness, and the name of the God of Abraham are further questions — some of them historical.</body>\n      <cite>Philoponus against an eternal world</cite>\n      <cite>al-Ghazālī and the kalām tradition</cite>\n      <cite>Craig’s modern statement of the kalām syllogism</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"25\">\n      <learn>If something begins, it has a cause. If this universe began, it has a cause. Naming Abraham’s God takes further historical steps.</learn>\n      <match sentence=\"If what begins has a cause and the universe began, it has a cause.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>A beginning has a Cause — more steps name God.</why>\n        <claimMiss>A cause of the beginning is already the whole creed.</claimMiss>\n        <claimMiss>The form never mentions a beginning.</claimMiss>\n        <whyMiss>The second premise cannot be argued at all.</whyMiss>\n        <whyMiss>A first cause automatically names Jesus.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>That yields a Cause of the beginning; naming Abraham’s God takes further historical steps.</learn>\n      <match sentence=\"If what begins has a cause and the universe began, it has a cause.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>That yields a Cause of the beginning; naming Abraham’s God takes further historical steps.</why>\n        <claimMiss>A cause of the beginning is already the whole creed.</claimMiss>\n        <claimMiss>The form never mentions a beginning.</claimMiss>\n        <whyMiss>The second premise cannot be argued at all.</whyMiss>\n        <whyMiss>A first cause automatically names Jesus.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Write the argument, then the best objection, then the reply. That is how these arguments have actually lived.</learn>\n      <match sentence=\"If what begins has a cause and the universe began, it has a cause.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>That yields a Cause of the beginning; naming Abraham’s God takes further historical steps.</why>\n        <claimMiss>A cause of the beginning is already the whole creed.</claimMiss>\n        <claimMiss>The form never mentions a beginning.</claimMiss>\n        <whyMiss>The second premise cannot be argued at all.</whyMiss>\n        <whyMiss>A first cause automatically names Jesus.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"fg-limits\" title=\"What the gate opens\" idea=\"a first cause is not yet the whole creed\">\n    <claim>A cosmological argument is already a great deal — and not yet the sermon on the mount.</claim>\n    <plain>A first cause is not yet the whole Christian faith.</plain>\n    <source>Aquinas ST I; Pascal on philosophers and Abraham</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <journal title=\"Honest limits\" kicker=\"Why Gate\">\n      <body>A sound cosmological argument is already a great deal. It is not yet the sermon on the mount, and it does not need to be. Aquinas does not stop at the Five Ways; he argues onward. The New Testament adds public claims about a particular life, death, and raising.</body>\n      <body>Pascal’s warning about the God of the philosophers is a warning against stopping. It is not a command to skip the philosophers.</body>\n      <cite>Aquinas, ST I, qq.2–26 (existence toward attributes)</cite>\n      <cite>Pascal, Pensées (God of Abraham / philosophers)</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"26\">\n      <learn>If the argument works, you have a first cause. Intellect, goodness, and the gospel are further steps — not leaks.</learn>\n      <match sentence=\"A cosmological argument is already a great deal — and not yet the sermon on the mount.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The first-cause walk is not yet the whole gospel.</why>\n        <claimMiss>The Five Ways are already the whole gospel.</claimMiss>\n        <claimMiss>Pascal commands you to skip the philosophers.</claimMiss>\n        <whyMiss>Stopping at a first cause is required.</whyMiss>\n        <whyMiss>History has nothing further to add.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Aquinas argues onward from the Ways; the New Testament adds a particular history.</learn>\n      <match sentence=\"A cosmological argument is already a great deal — and not yet the sermon on the mount.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Aquinas argues onward from the Ways; the New Testament adds a particular history.</why>\n        <claimMiss>The Five Ways are already the whole gospel.</claimMiss>\n        <claimMiss>Pascal commands you to skip the philosophers.</claimMiss>\n        <whyMiss>Stopping at a first cause is required.</whyMiss>\n        <whyMiss>History has nothing further to add.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Pascal’s warning about the God of the philosophers is a warning against stopping — not a command to skip the philosophers.</learn>\n      <match sentence=\"A cosmological argument is already a great deal — and not yet the sermon on the mount.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>Aquinas argues onward from the Ways; the New Testament adds a particular history.</why>\n        <claimMiss>The Five Ways are already the whole gospel.</claimMiss>\n        <claimMiss>Pascal commands you to skip the philosophers.</claimMiss>\n        <whyMiss>Stopping at a first cause is required.</whyMiss>\n        <whyMiss>History has nothing further to add.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-scroll\" title=\"A copied line\" idea=\"the Bible we hold arrived through a river of copies\">\n    <claim>We hold a river of copies, not the first ink.</claim>\n    <plain>We hold a river of copies, not the first ink.</plain>\n    <source>Isaiah 40:8</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <easy points=\"10\" easyOrder=\"27\">\n      <learn>Scribes copy. Later hands compare. Then a page prints a recovered text. The word still stands.</learn>\n      <match sentence=\"We hold a river of copies, not the first ink.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Scribes copy, later hands compare, then we print it.</why>\n        <claimMiss>We hold the first ink in a glass case.</claimMiss>\n        <claimMiss>Comparison of copies is cheating.</claimMiss>\n        <whyMiss>A line falls from the sky onto a printer.</whyMiss>\n        <whyMiss>Transmission has no human hands.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Scribes copy, later hands compare, then a modern page prints a recovered text.</learn>\n      <match sentence=\"We hold a river of copies, not the first ink.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Scribes copy, later hands compare, then a modern page prints a recovered text.</why>\n        <claimMiss>We hold the first ink in a glass case.</claimMiss>\n        <claimMiss>Comparison of copies is cheating.</claimMiss>\n        <whyMiss>A line falls from the sky onto a printer.</whyMiss>\n        <whyMiss>Transmission has no human hands.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Isaiah 40:8: the grass withers, the flower fades, but the word of our God will stand forever.</learn>\n      <match sentence=\"We hold a river of copies, not the first ink.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>Scribes copy, later hands compare, then a modern page prints a recovered text.</why>\n        <claimMiss>We hold the first ink in a glass case.</claimMiss>\n        <claimMiss>Comparison of copies is cheating.</claimMiss>\n        <whyMiss>A line falls from the sky onto a printer.</whyMiss>\n        <whyMiss>Transmission has no human hands.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-isaiah\" title=\"A hard poem\" idea=\"Isaiah 53’s Servant is the Jesus the church confesses\">\n    <claim>Isaiah 53’s Servant is the Jesus the church confesses — wounded for others, silent like a lamb.</claim>\n    <plain>Isaiah 53’s Servant is the Jesus the church confesses — wounded for others, silent like a lamb.</plain>\n    <source>Isaiah 53:4–12</source>\n    <loci place=\"Why Gate\" person=\"Ansel Gate\" plotId=\"gate\" who=\"ansel\" />\n    <easy points=\"10\" easyOrder=\"28\">\n      <learn>The poem’s Servant suffers for others and does not answer with a sword. The church names that Servant as Jesus.</learn>\n      <match sentence=\"Isaiah 53’s Servant is the Jesus the church confesses — wounded for others, silent like a lamb.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The Servant suffers for others — the church names Jesus.</why>\n        <claimMiss>The servant conquers Rome by sword.</claimMiss>\n        <claimMiss>The poem is about estate planning.</claimMiss>\n        <whyMiss>The servant never suffers for anyone.</whyMiss>\n        <whyMiss>Wounds are unrelated to healing in the poem.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The poem’s Servant suffers for others and does not answer with a sword; the church names that Servant as Jesus.</learn>\n      <match sentence=\"Isaiah 53’s Servant is the Jesus the church confesses — wounded for others, silent like a lamb.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The poem’s Servant suffers for others and does not answer with a sword; the church names that Servant as Jesus.</why>\n        <claimMiss>The servant conquers Rome by sword.</claimMiss>\n        <claimMiss>The poem is about estate planning.</claimMiss>\n        <whyMiss>The servant never suffers for anyone.</whyMiss>\n        <whyMiss>Wounds are unrelated to healing in the poem.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>He was pierced for our transgressions… and with his wounds we are healed.</learn>\n      <match sentence=\"Isaiah 53’s Servant is the Jesus the church confesses — wounded for others, silent like a lamb.\" place=\"Why Gate\" person=\"Ansel Gate\" />\n      <hold onFail=\"easy\">\n        <why>The poem’s Servant suffers for others and does not answer with a sword; the church names that Servant as Jesus.</why>\n        <claimMiss>The servant conquers Rome by sword.</claimMiss>\n        <claimMiss>The poem is about estate planning.</claimMiss>\n        <whyMiss>The servant never suffers for anyone.</whyMiss>\n        <whyMiss>Wounds are unrelated to healing in the poem.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n</area>\n",
  "high-lookout.xml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<area schemaVersion=\"3\" id=\"high-lookout\" order=\"5\" title=\"Meaning Ridge\" shortTitle=\"Meaning\" subtitle=\"Mind, duty, meaning, and beauty\" icon=\"peak\" accent=\"#b86b8a\">\n  <blurb>The trail turns inward: why do we know good, and why does beauty wound us?</blurb>\n  <intro>The path ends — and does not end — on a lookout where the whole town lies below. Here the clues are closer than stars: conscience, consciousness, the ache for meaning, the strange authority of beauty.</intro>\n  <intro>These are not laboratory instruments. They are the conditions under which any instrument is used. Ignore them, and the case for God is thinner than it should be. Inflate them, and you preach at a wound instead of thinking with it.</intro>\n  <intro>Take each as a signpost. Signposts do not drag you. They tell you a country may be real.</intro>\n  <lesson id=\"hl-moral\" title=\"The grain of duty\" idea=\"duty feels real, not like a taste for tea\">\n    <claim>Duty presents itself as more than taste — and theism is a natural home for that.</claim>\n    <plain>Duty feels real — not like a taste for tea.</plain>\n    <source>Romans 2:14–15</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <journal title=\"The moral grain of the world\" kicker=\"Meaning Ridge\">\n      <body>Duty presents itself as more than taste. A good God is the ground of a good law — the home that fits. Romans 2 treats that knowledge as widely shared, which is why injustice still has a name.</body>\n      <body>Romans 2:14–15 treats moral knowledge as widely shared. That is why strangers can still accuse one another of injustice and expect the accusation to mean something.</body>\n      <cite>Romans 2:14–15</cite>\n      <cite>Aquinas, ST I-II, q.91</cite>\n      <cite>Augustine, City of God XIX</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"29\">\n      <learn>Duty is more than a taste. Romans 2 says strangers already know enough to accuse one another.</learn>\n      <match sentence=\"Duty presents itself as more than taste — and theism is a natural home for that.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>We all know duty — strangers can still accuse.</why>\n        <claimMiss>Duty is only a preference we pretend is law.</claimMiss>\n        <claimMiss>Atheist moral realism is impossible to name.</claimMiss>\n        <whyMiss>Moral argument is a sneer at people who doubt.</whyMiss>\n        <whyMiss>Strangers cannot expect injustice to mean anything.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Romans 2 treats moral knowledge as widely shared, which is why strangers can accuse one another.</learn>\n      <match sentence=\"Duty presents itself as more than taste — and theism is a natural home for that.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Romans 2 treats moral knowledge as widely shared, which is why strangers can accuse one another.</why>\n        <claimMiss>Duty is only a preference we pretend is law.</claimMiss>\n        <claimMiss>Atheist moral realism is impossible to name.</claimMiss>\n        <whyMiss>Moral argument is a sneer at people who doubt.</whyMiss>\n        <whyMiss>Strangers cannot expect injustice to mean anything.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Romans 2:14–15 speaks of a law “written on the heart.” That is not a sneer at people who doubt. It is a claim that moral knowledge is widely shared — which is why we can argue about it at all.</learn>\n      <match sentence=\"Duty presents itself as more than taste — and theism is a natural home for that.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>Romans 2 treats moral knowledge as widely shared, which is why strangers can accuse one another.</why>\n        <claimMiss>Duty is only a preference we pretend is law.</claimMiss>\n        <claimMiss>Atheist moral realism is impossible to name.</claimMiss>\n        <whyMiss>Moral argument is a sneer at people who doubt.</whyMiss>\n        <whyMiss>Strangers cannot expect injustice to mean anything.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"hl-mind\" title=\"The inside of mind\" idea=\"inner experience is not captured by a scan\">\n    <claim>A story of the world must find a home for mind — including the storyteller.</claim>\n    <plain>Inner experience is not captured by a scan.</plain>\n    <source>The hard problem; classical theism on intellect</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <journal title=\"The inside of mind\" kicker=\"Meaning Ridge\">\n      <body>Qualia, aboutness, the hard problem, and the norm of reason are not parlor tricks. They are what it is like to be a knower. A story of the world that cannot find a home for mind is a story that cannot find a home for the storyteller.</body>\n      <body>A living God is the home of mind: not an accident at the end of an indifferent process, but present at the beginning.</body>\n      <cite>Augustine, De Trinitate X</cite>\n      <cite>John 1:1–4</cite>\n      <cite>Classical theism on God as living intellect</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"30\">\n      <learn>Felt redness, thoughts about things, and the pull of truth are not just collisions. Mind is at home if the world’s ground is a living God.</learn>\n      <match sentence=\"A story of the world must find a home for mind — including the storyteller.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Mind is there at the start — not a late accident.</why>\n        <claimMiss>Qualia and aboutness are parlor tricks.</claimMiss>\n        <claimMiss>Theism is the only reply anyone has offered.</claimMiss>\n        <whyMiss>A story without mind can still house the storyteller with no remainder.</whyMiss>\n        <whyMiss>Mind is easy to treat as leftover steam.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Theism is a reply in which mind is present at the beginning, not only an accident at the end.</learn>\n      <match sentence=\"A story of the world must find a home for mind — including the storyteller.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Theism is a reply in which mind is present at the beginning, not only an accident at the end.</why>\n        <claimMiss>Qualia and aboutness are parlor tricks.</claimMiss>\n        <claimMiss>Theism is the only reply anyone has offered.</claimMiss>\n        <whyMiss>A story without mind can still house the storyteller with no remainder.</whyMiss>\n        <whyMiss>Mind is easy to treat as leftover steam.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>A living God is the home of mind. Materialism hopes a future theory will close the gap. Hold the claim: inner life is not an accident at the end of indifference.</learn>\n      <match sentence=\"A story of the world must find a home for mind — including the storyteller.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>Theism is a reply in which mind is present at the beginning, not only an accident at the end.</why>\n        <claimMiss>Qualia and aboutness are parlor tricks.</claimMiss>\n        <claimMiss>Theism is the only reply anyone has offered.</claimMiss>\n        <whyMiss>A story without mind can still house the storyteller with no remainder.</whyMiss>\n        <whyMiss>Mind is easy to treat as leftover steam.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"hl-meaning\" title=\"Invented or found\" idea=\"meaning is found, not only invented\">\n    <claim>Local meaning can be built — the lookout asks whether it is also received.</claim>\n    <plain>You can build a local meaning. The lookout asks if it is also received.</plain>\n    <source>Ecclesiastes 2; 9; 12</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <journal title=\"Meaning that can be found\" kicker=\"Meaning Ridge\">\n      <body>You can build a local meaning without naming God. The lookout asks whether that meaning is only assembled, or also received — whether the hunger for a final good has an object.</body>\n      <body>Ecclesiastes refuses to let work and pleasure pretend to be the final good, and also refuses to call them worthless as gifts. That double honesty is part of biblical wisdom.</body>\n      <cite>Ecclesiastes 2:24; 9:7–10; 12:13</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"31\">\n      <learn>Work and pleasure are gifts. They are not the final good. Ecclesiastes keeps both truths.</learn>\n      <match sentence=\"Local meaning can be built — the lookout asks whether it is also received.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Work and fun are gifts — not the last good.</why>\n        <claimMiss>Work and pleasure are the final good.</claimMiss>\n        <claimMiss>Ecclesiastes calls every gift worthless.</claimMiss>\n        <whyMiss>The hunger for a final good has no question attached.</whyMiss>\n        <whyMiss>You cannot build any local meaning without naming God.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Ecclesiastes refuses to let work and pleasure pretend to be the final good, and refuses to call them worthless as gifts.</learn>\n      <match sentence=\"Local meaning can be built — the lookout asks whether it is also received.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Ecclesiastes refuses to let work and pleasure pretend to be the final good, and refuses to call them worthless as gifts.</why>\n        <claimMiss>Work and pleasure are the final good.</claimMiss>\n        <claimMiss>Ecclesiastes calls every gift worthless.</claimMiss>\n        <whyMiss>The hunger for a final good has no question attached.</whyMiss>\n        <whyMiss>You cannot build any local meaning without naming God.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>If God is the good that created goods point toward, ordinary loves are not canceled. They are promised a future.</learn>\n      <match sentence=\"Local meaning can be built — the lookout asks whether it is also received.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>Ecclesiastes refuses to let work and pleasure pretend to be the final good, and refuses to call them worthless as gifts.</why>\n        <claimMiss>Work and pleasure are the final good.</claimMiss>\n        <claimMiss>Ecclesiastes calls every gift worthless.</claimMiss>\n        <whyMiss>The hunger for a final good has no question attached.</whyMiss>\n        <whyMiss>You cannot build any local meaning without naming God.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"hl-beauty\" title=\"Homesick at the music\" idea=\"beauty wakes a hunger it cannot feed\">\n    <claim>Beauty wakes a hunger it cannot feed — hungers usually correspond to real countries.</claim>\n    <plain>Beauty wakes a hunger it cannot feed — longing for a country the sunset cannot give.</plain>\n    <source>Lewis, Weight of Glory; Psalm 19:1–4</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <journal title=\"Beauty as a signpost\" kicker=\"Meaning Ridge\">\n      <body>Beauty wakes a hunger it cannot feed — longing for a country the sunset cannot give. Hungers like that usually correspond to real countries.</body>\n      <body>Psalm 19 treats the sky as speech. The observatory and the lookout are the same ridge at two hours of the day: measurement at dusk, longing after dark. The trail is unending because the object, if real, is not smaller than a game.</body>\n      <cite>C. S. Lewis, “The Weight of Glory”; Surprised by Joy</cite>\n      <cite>Psalm 19:1–4</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"32\">\n      <learn>Psalm 19 treats the sky as speech. Hungers like that usually correspond to real countries.</learn>\n      <match sentence=\"Beauty wakes a hunger it cannot feed — hungers usually correspond to real countries.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The sunset wakes a hunger it cannot feed.</why>\n        <claimMiss>A sunset deducts God as a theorem.</claimMiss>\n        <claimMiss>Hungers never correspond to real countries.</claimMiss>\n        <whyMiss>Psalm 19 treats the sky as silent decoration.</whyMiss>\n        <whyMiss>The lookout and the observatory cannot share a ridge.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Longing for a country the sunset cannot give is a mark that we were made for that country; Psalm 19 treats the sky as speech.</learn>\n      <match sentence=\"Beauty wakes a hunger it cannot feed — hungers usually correspond to real countries.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Longing for a country the sunset cannot give is a mark that we were made for that country; Psalm 19 treats the sky as speech.</why>\n        <claimMiss>A sunset deducts God as a theorem.</claimMiss>\n        <claimMiss>Hungers never correspond to real countries.</claimMiss>\n        <whyMiss>Psalm 19 treats the sky as silent decoration.</whyMiss>\n        <whyMiss>The lookout and the observatory cannot share a ridge.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Beauty does not replace the earlier areas. It keeps them from becoming only a brief.</learn>\n      <match sentence=\"Beauty wakes a hunger it cannot feed — hungers usually correspond to real countries.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>Longing for a country the sunset cannot give is a mark that we were made for that country; Psalm 19 treats the sky as speech.</why>\n        <claimMiss>A sunset deducts God as a theorem.</claimMiss>\n        <claimMiss>Hungers never correspond to real countries.</claimMiss>\n        <whyMiss>Psalm 19 treats the sky as silent decoration.</whyMiss>\n        <whyMiss>The lookout and the observatory cannot share a ridge.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-grace\" title=\"Not a wage\" idea=\"grace is a gift, not a wage\">\n    <claim>Grace is gift, not wage; faith receives; boast starves.</claim>\n    <plain>Grace is gift, not wage. Faith receives. Boast starves.</plain>\n    <source>Ephesians 2:8–9</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <easy points=\"10\" easyOrder=\"33\">\n      <learn>God moves first. You did not finish a map that earned this.</learn>\n      <match sentence=\"Grace is gift, not wage; faith receives; boast starves.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>God moves first — you did not finish the map.</why>\n        <claimMiss>Grace is a prize for high scores.</claimMiss>\n        <claimMiss>Faith is a wage God owes you.</claimMiss>\n        <whyMiss>Boast is what the gift is for.</whyMiss>\n        <whyMiss>Salvation is your own doing.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The claim is that God moves first — not that you finished the map.</learn>\n      <match sentence=\"Grace is gift, not wage; faith receives; boast starves.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The claim is that God moves first — not that you finished the map.</why>\n        <claimMiss>Grace is a prize for high scores.</claimMiss>\n        <claimMiss>Faith is a wage God owes you.</claimMiss>\n        <whyMiss>Boast is what the gift is for.</whyMiss>\n        <whyMiss>Salvation is your own doing.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>By grace you have been saved through faith. And this is not your own doing; it is the gift of God.</learn>\n      <match sentence=\"Grace is gift, not wage; faith receives; boast starves.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>The claim is that God moves first — not that you finished the map.</why>\n        <claimMiss>Grace is a prize for high scores.</claimMiss>\n        <claimMiss>Faith is a wage God owes you.</claimMiss>\n        <whyMiss>Boast is what the gift is for.</whyMiss>\n        <whyMiss>Salvation is your own doing.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-rest\" title=\"Come and rest\" idea=\"rest is offered to tired people first\">\n    <claim>Tired people are named first; rest is the gift, not a steeper hill.</claim>\n    <plain>Tired people are named first. Rest is the gift, not a steeper hill.</plain>\n    <source>Matthew 11:28</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <easy points=\"10\" easyOrder=\"34\">\n      <learn>The invitation is to a person — “Come to me” — not a performance.</learn>\n      <match sentence=\"Tired people are named first; rest is the gift, not a steeper hill.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Come to me — rest is a gift, not a show.</why>\n        <claimMiss>Rest is a prize for climbing harder.</claimMiss>\n        <claimMiss>Jesus names the energetic first.</claimMiss>\n        <whyMiss>The invitation is to a steeper program.</whyMiss>\n        <whyMiss>Weariness disqualifies you.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The invitation is to a person — “Come to me” — not a performance.</learn>\n      <match sentence=\"Tired people are named first; rest is the gift, not a steeper hill.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The invitation is to a person — “Come to me” — not a performance.</why>\n        <claimMiss>Rest is a prize for climbing harder.</claimMiss>\n        <claimMiss>Jesus names the energetic first.</claimMiss>\n        <whyMiss>The invitation is to a steeper program.</whyMiss>\n        <whyMiss>Weariness disqualifies you.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Come to me, all who labor and are heavy laden, and I will give you rest.</learn>\n      <match sentence=\"Tired people are named first; rest is the gift, not a steeper hill.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>The invitation is to a person — “Come to me” — not a performance.</why>\n        <claimMiss>Rest is a prize for climbing harder.</claimMiss>\n        <claimMiss>Jesus names the energetic first.</claimMiss>\n        <whyMiss>The invitation is to a steeper program.</whyMiss>\n        <whyMiss>Weariness disqualifies you.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-door\" title=\"A door, not a wall\" idea=\"Jesus claims to be a door in, not a wall\">\n    <claim>Jesus’ “door” is a particular way in with a wide anyone.</claim>\n    <plain>Jesus’ “door” is a particular way in with a wide anyone.</plain>\n    <source>John 10:9</source>\n    <loci place=\"Meaning Ridge\" person=\"Hope Ridge\" plotId=\"lookout\" who=\"hope\" />\n    <easy points=\"10\" easyOrder=\"35\">\n      <learn>You may refuse it. The town will not lock you in a pew.</learn>\n      <match sentence=\"Jesus’ “door” is a particular way in with a wide anyone.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>You may refuse — no one locks you in a pew.</why>\n        <claimMiss>The door is a dead end.</claimMiss>\n        <claimMiss>Pasture is denied on the other side.</claimMiss>\n        <whyMiss>“Anyone” is narrowed to insiders only.</whyMiss>\n        <whyMiss>The image is a wall, not an entrance.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>You may refuse it; the town will not lock you in a pew.</learn>\n      <match sentence=\"Jesus’ “door” is a particular way in with a wide anyone.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>You may refuse it; the town will not lock you in a pew.</why>\n        <claimMiss>The door is a dead end.</claimMiss>\n        <claimMiss>Pasture is denied on the other side.</claimMiss>\n        <whyMiss>“Anyone” is narrowed to insiders only.</whyMiss>\n        <whyMiss>The image is a wall, not an entrance.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>I am the door. If anyone enters by me, he will be saved and will go in and out and find pasture.</learn>\n      <match sentence=\"Jesus’ “door” is a particular way in with a wide anyone.\" place=\"Meaning Ridge\" person=\"Hope Ridge\" />\n      <hold onFail=\"easy\">\n        <why>You may refuse it; the town will not lock you in a pew.</why>\n        <claimMiss>The door is a dead end.</claimMiss>\n        <claimMiss>Pasture is denied on the other side.</claimMiss>\n        <whyMiss>“Anyone” is narrowed to insiders only.</whyMiss>\n        <whyMiss>The image is a wall, not an entrance.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n</area>\n",
  "index.xml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<packIndex schemaVersion=\"3\" id=\"core-v0\" title=\"Core trail\">\n  <area file=\"parable-hollow.xml\" id=\"parable-hollow\" />\n  <area file=\"witness-bench.xml\" id=\"witness-bench\" />\n  <area file=\"observatory.xml\" id=\"observatory\" />\n  <area file=\"first-gate.xml\" id=\"first-gate\" />\n  <area file=\"high-lookout.xml\" id=\"high-lookout\" />\n  <area id=\"east-porch\" order=\"0\" title=\"East porch\" shortTitle=\"Porch\" subtitle=\"A lamp is meant to be seen\" icon=\"lamp\" accent=\"#ffcc33\">\n    <blurb>Juniper’s lamp. You arrive here so today’s line can be seen.</blurb>\n    <intro>The east porch is where a line can be seen. Juniper keeps the lamp.</intro>\n  <lesson id=\"daily-lantern\" title=\"The porch lamp\" idea=\"a city on a hill is meant to be seen\">\n    <claim>A lamp is meant to be seen.</claim>\n    <plain>A lamp is meant to be seen.</plain>\n    <source>Matthew 5:14–16</source>\n    <loci place=\"East porch\" person=\"Juniper Wick\" plotId=\"porch\" who=\"juniper\" />\n    <easy points=\"10\" easyOrder=\"12\">\n      <learn>Jesus uses an ordinary lamp and a city on a hill. Public without being proud.</learn>\n      <match sentence=\"A lamp is meant to be seen.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>A lamp and a hill city are meant to be seen.</why>\n        <claimMiss>We are told to become the sun.</claimMiss>\n        <claimMiss>Light is only for insiders behind a door.</claimMiss>\n        <whyMiss>The picture is a command to boast.</whyMiss>\n        <whyMiss>A hidden lamp is the point of the saying.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Jesus uses an ordinary lamp and a city on a hill — public without being proud.</learn>\n      <match sentence=\"A lamp is meant to be seen.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Jesus uses an ordinary lamp and a city on a hill — public without being proud.</why>\n        <claimMiss>We are told to become the sun.</claimMiss>\n        <claimMiss>Light is only for insiders behind a door.</claimMiss>\n        <whyMiss>The picture is a command to boast.</whyMiss>\n        <whyMiss>A hidden lamp is the point of the saying.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>“You are the light of the world. A city set on a hill cannot be hidden.” The picture is public without being proud.</learn>\n      <match sentence=\"A lamp is meant to be seen.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold onFail=\"easy\">\n        <why>Jesus uses an ordinary lamp and a city on a hill — public without being proud.</why>\n        <claimMiss>We are told to become the sun.</claimMiss>\n        <claimMiss>Light is only for insiders behind a door.</claimMiss>\n        <whyMiss>The picture is a command to boast.</whyMiss>\n        <whyMiss>A hidden lamp is the point of the saying.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-gems\" title=\"Porch gems\" idea=\"Jesus taught with pictures you can hold\">\n    <claim>Jesus taught with pictures you can hold.</claim>\n    <plain>Jesus taught with pictures you can hold.</plain>\n    <source>Matthew 5; Mark 4; Matthew 26:28; Luke 22:20</source>\n    <loci place=\"East porch\" person=\"Juniper Wick\" plotId=\"porch\" who=\"juniper\" />\n    <easy points=\"10\" easyOrder=\"13\">\n      <learn>A lamp is seen. Seed meets different hearts. The cup is poured for many — gift, not wage.</learn>\n      <match sentence=\"Jesus taught with pictures you can hold.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Lamp, seed, and cup are gifts you can hold.</why>\n        <claimMiss>Pictures are only decoration.</claimMiss>\n        <claimMiss>Mercy is a wage you finish earning.</claimMiss>\n        <whyMiss>Every heart is the same soil.</whyMiss>\n        <whyMiss>A hidden lamp is the point.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>A lamp is seen, seed meets different hearts, and the cup is poured for many — gift, not wage.</learn>\n      <match sentence=\"Jesus taught with pictures you can hold.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>A lamp is seen, seed meets different hearts, and the cup is poured for many — gift, not wage.</why>\n        <claimMiss>Pictures are only decoration.</claimMiss>\n        <claimMiss>Mercy is a wage you finish earning.</claimMiss>\n        <whyMiss>Every heart is the same soil.</whyMiss>\n        <whyMiss>A hidden lamp is the point.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Jesus taught with lamps, seed, and a cup. The cup of the new covenant is poured for many (Matthew 26:28; Luke 22:20) — gift, not wage.</learn>\n      <match sentence=\"Jesus taught with pictures you can hold.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold onFail=\"easy\">\n        <why>A lamp is seen, seed meets different hearts, and the cup is poured for many — gift, not wage.</why>\n        <claimMiss>Pictures are only decoration.</claimMiss>\n        <claimMiss>Mercy is a wage you finish earning.</claimMiss>\n        <whyMiss>Every heart is the same soil.</whyMiss>\n        <whyMiss>A hidden lamp is the point.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-seed\" title=\"A handful of seed\" idea=\"the same word meets very different hearts\">\n    <claim>The same word meets different soils; some seed is lost.</claim>\n    <plain>The same word meets different soils. Some seed is lost.</plain>\n    <source>Mark 4:1–9</source>\n    <loci place=\"East porch\" person=\"Juniper Wick\" plotId=\"porch\" who=\"juniper\" />\n    <easy points=\"10\" easyOrder=\"14\">\n      <learn>This Jesus story invites hearing. It does not flatter every field.</learn>\n      <match sentence=\"The same word meets different soils; some seed is lost.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Not every field is good soil.</why>\n        <claimMiss>Every field is guaranteed a harvest.</claimMiss>\n        <claimMiss>Lost seed means the sower failed.</claimMiss>\n        <whyMiss>Good soil is a slogan, not a way of hearing.</whyMiss>\n        <whyMiss>Jesus never names withering or birds.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The parable invites hearing; it does not flatter every field.</learn>\n      <match sentence=\"The same word meets different soils; some seed is lost.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The parable invites hearing; it does not flatter every field.</why>\n        <claimMiss>Every field is guaranteed a harvest.</claimMiss>\n        <claimMiss>Lost seed means the sower failed.</claimMiss>\n        <whyMiss>Good soil is a slogan, not a way of hearing.</whyMiss>\n        <whyMiss>Jesus never names withering or birds.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>“He who has ears to hear, let him hear.” The story asks for a kind of soil, not a slogan.</learn>\n      <match sentence=\"The same word meets different soils; some seed is lost.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold onFail=\"easy\">\n        <why>The parable invites hearing; it does not flatter every field.</why>\n        <claimMiss>Every field is guaranteed a harvest.</claimMiss>\n        <claimMiss>Lost seed means the sower failed.</claimMiss>\n        <whyMiss>Good soil is a slogan, not a way of hearing.</whyMiss>\n        <whyMiss>Jesus never names withering or birds.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-neighbor\" title=\"Who is near\" idea=\"neighbor is the one who shows mercy\">\n    <claim>Mercy makes a neighbor; pedigree does not.</claim>\n    <plain>Mercy makes a neighbor. Pedigree does not.</plain>\n    <source>Luke 10:36–37</source>\n    <loci place=\"East porch\" person=\"Juniper Wick\" plotId=\"porch\" who=\"juniper\" />\n    <easy points=\"10\" easyOrder=\"15\">\n      <learn>Jesus asks who *proved* to be a neighbor — the one who showed mercy.</learn>\n      <match sentence=\"Mercy makes a neighbor; pedigree does not.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Jesus asks who showed mercy — that one is neighbor.</why>\n        <claimMiss>The priest who passed by is the measure.</claimMiss>\n        <claimMiss>Neighbor is settled before anyone crosses the road.</claimMiss>\n        <whyMiss>Mercy is unrelated to the question.</whyMiss>\n        <whyMiss>The wounded man must first classify the helper.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Jesus asks who *proved* to be a neighbor — the one who showed mercy.</learn>\n      <match sentence=\"Mercy makes a neighbor; pedigree does not.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Jesus asks who *proved* to be a neighbor — the one who showed mercy.</why>\n        <claimMiss>The priest who passed by is the measure.</claimMiss>\n        <claimMiss>Neighbor is settled before anyone crosses the road.</claimMiss>\n        <whyMiss>Mercy is unrelated to the question.</whyMiss>\n        <whyMiss>The wounded man must first classify the helper.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>He said, “The one who showed him mercy.” And Jesus said, “You go, and do likewise.”</learn>\n      <match sentence=\"Mercy makes a neighbor; pedigree does not.\" place=\"East porch\" person=\"Juniper Wick\" />\n      <hold onFail=\"easy\">\n        <why>Jesus asks who *proved* to be a neighbor — the one who showed mercy.</why>\n        <claimMiss>The priest who passed by is the measure.</claimMiss>\n        <claimMiss>Neighbor is settled before anyone crosses the road.</claimMiss>\n        <whyMiss>Mercy is unrelated to the question.</whyMiss>\n        <whyMiss>The wounded man must first classify the helper.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  </area>\n</packIndex>\n",
  "observatory.xml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<area schemaVersion=\"3\" id=\"observatory\" order=\"3\" title=\"Sky Watch\" shortTitle=\"Sky\" subtitle=\"A sky that did not have to be this way\" icon=\"star\" accent=\"#7f9ec7\">\n  <blurb>Science maps how the world runs. It does not forbid the question why.</blurb>\n  <intro>Above the ridge a small observatory points at winter stars. The question here is not “Does a lab experiment prove God?” That would confuse the tools.</intro>\n  <intro>The question is: what kind of universe is this? Why are its laws hospitable to life? Why is there a concrete world with laws at all?</intro>\n  <intro>Fine-tuning, origins, and “something rather than nothing” begin from public facts and make a case for God. Hold the claim. Deploy it. The sky is not a shrug.</intro>\n  <lesson id=\"ob-tuning\" title=\"Narrow ranges\" idea=\"the universe is finely tuned for life — that fit points to a Designer\">\n    <claim>The universe is finely tuned for life — that fit points to a Designer.</claim>\n    <plain>The universe is finely tuned for life — that fit points to a Designer.</plain>\n    <source>Fine-tuning of physical constants and initial conditions (e.g. cosmological constant; a low-entropy start — initial condition, not another force dial).</source>\n    <loci place=\"Sky Watch\" person=\"Nora Skye\" plotId=\"observatory\" who=\"nora\" />\n    <journal title=\"The universe is finely tuned for life\" kicker=\"Sky Watch\">\n      <body>The universe is finely tuned for life — that fit points to a Designer.</body>\n      <body>Life-permitting ranges are extravagantly narrow across independent parameters; design predicts a habitable cosmos, blank chance does not.</body>\n      <cite>Fine-tuning of physical constants and initial conditions (e.g. cosmological constant; a low-entropy start — an initial condition, not another force dial).</cite>\n      <cite>Aquinas, ST I, q.2, a.3 (Fifth Way); Psalm 19; Romans 1</cite>\n      <cite>Robin Collins, The Fine-Tuning Design Argument</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"16\">\n      <learn>Life needs very tight numbers: how fast space expands, how atoms stick, how tidy the start was. Design predicts a world we can live in. Blind chance does not.</learn>\n      <match sentence=\"The universe is finely tuned for life — that fit points to a Designer.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Life needs tight numbers — chance does not explain that.</why>\n        <claimMiss>Fine-tuning is a rumor with no name in science.</claimMiss>\n        <claimMiss>A habitable cosmos needs no explanation at all.</claimMiss>\n        <whyMiss>Life-permitting ranges are wide; blank chance predicts a habitable cosmos just as well.</whyMiss>\n        <whyMiss>The fittedness is only a rumor in the numbers.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Life-permitting ranges are extravagantly narrow across independent parameters; design predicts a habitable cosmos, blank chance does not.</learn>\n      <match sentence=\"The universe is finely tuned for life — that fit points to a Designer.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Life-permitting ranges are extravagantly narrow across independent parameters; design predicts a habitable cosmos, blank chance does not.</why>\n        <claimMiss>Fine-tuning is a rumor with no name in science.</claimMiss>\n        <claimMiss>A habitable cosmos needs no explanation at all.</claimMiss>\n        <whyMiss>Life-permitting ranges are wide; blank chance predicts a habitable cosmos just as well.</whyMiss>\n        <whyMiss>The fittedness is only a rumor in the numbers.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Design predicts this cosmos: cosmological constant, nuclear binding, a low-entropy start, gravity against electromagnetism — extravagantly narrow, habitable. That fit points to a Designer.</learn>\n      <match sentence=\"The universe is finely tuned for life — that fit points to a Designer.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold onFail=\"easy\">\n        <why>Life-permitting ranges are extravagantly narrow across independent parameters; design predicts a habitable cosmos, blank chance does not.</why>\n        <claimMiss>Fine-tuning is a rumor with no name in science.</claimMiss>\n        <claimMiss>A habitable cosmos needs no explanation at all.</claimMiss>\n        <whyMiss>Life-permitting ranges are wide; blank chance predicts a habitable cosmos just as well.</whyMiss>\n        <whyMiss>The fittedness is only a rumor in the numbers.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"ob-design\" title=\"A habitable cosmos\" idea=\"fine-tuning is best explained by a mind that intended a habitable world\">\n    <claim>Fine-tuning is best explained by a mind that intended a habitable world.</claim>\n    <plain>Fine-tuning is best explained by a mind that intended a habitable world.</plain>\n    <source>Likelihood / fine-tuning arguments (Collins). A low-entropy start is an initial condition, not another force dial.</source>\n    <loci place=\"Sky Watch\" person=\"Nora Skye\" plotId=\"observatory\" who=\"nora\" />\n    <journal title=\"A mind that intended a habitable world\" kicker=\"Sky Watch\">\n      <body>Fine-tuning is best explained by a mind that intended a habitable world.</body>\n      <body>Life-permitting ranges are extravagantly narrow; a Designer who wants observers leads us to expect that fit — blank indifference does not.</body>\n      <cite>Likelihood / fine-tuning arguments (Collins). A low-entropy start is an initial condition, not another force dial.</cite>\n      <cite>Aquinas, ST I, q.2, a.3 (Fifth Way); Psalm 19; Romans 1</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"17\">\n      <learn>The ranges are extravagantly narrow. A Designer who wants observers leads us to expect that fit. A world that does not care does not.</learn>\n      <match sentence=\"Fine-tuning is best explained by a mind that intended a habitable world.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>A Designer who wants people fits these numbers.</why>\n        <claimMiss>A habitable cosmos needs no Designer.</claimMiss>\n        <claimMiss>Fine-tuning already proves a particular gospel.</claimMiss>\n        <whyMiss>A mind wanting observers would not expect life-permitting numbers.</whyMiss>\n        <whyMiss>Likelihood arguments are automatically dishonest.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Life-permitting ranges are extravagantly narrow; a Designer who wants observers leads us to expect that fit — blank indifference does not.</learn>\n      <match sentence=\"Fine-tuning is best explained by a mind that intended a habitable world.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Life-permitting ranges are extravagantly narrow; a Designer who wants observers leads us to expect that fit — blank indifference does not.</why>\n        <claimMiss>A habitable cosmos needs no Designer.</claimMiss>\n        <claimMiss>Fine-tuning already proves a particular gospel.</claimMiss>\n        <whyMiss>A mind wanting observers would not expect life-permitting numbers.</whyMiss>\n        <whyMiss>Likelihood arguments are automatically dishonest.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>A Designer who wants observers predicts this habitable fit. The narrow ranges are the evidence. Hold the Designer.</learn>\n      <match sentence=\"Fine-tuning is best explained by a mind that intended a habitable world.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold onFail=\"easy\">\n        <why>Life-permitting ranges are extravagantly narrow; a Designer who wants observers leads us to expect that fit — blank indifference does not.</why>\n        <claimMiss>A habitable cosmos needs no Designer.</claimMiss>\n        <claimMiss>Fine-tuning already proves a particular gospel.</claimMiss>\n        <whyMiss>A mind wanting observers would not expect life-permitting numbers.</whyMiss>\n        <whyMiss>Likelihood arguments are automatically dishonest.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"ob-leibniz\" title=\"Something rather than nothing\" idea=\"physics maps how the world runs; it does not finish why\">\n    <claim>Why is there something rather than nothing remains after a cosmological model.</claim>\n    <plain>Physics maps how the world runs. It does not finish why there is a world.</plain>\n    <source>Leibniz; the vacuum/nothing distinction</source>\n    <loci place=\"Sky Watch\" person=\"Nora Skye\" plotId=\"observatory\" who=\"nora\" />\n    <journal title=\"The question beneath physics\" kicker=\"Sky Watch\">\n      <body>Leibniz’s question — why is there something rather than nothing? — is not retired by a successful cosmological model. Models describe a world that is already given.</body>\n      <body>When popular writing says the universe came from “nothing,” check whether the word still names a vacuum, a law, or a formalism. Those are somethings. The metaphysical question remains on the table.</body>\n      <cite>Leibniz, “On the Ultimate Origination of Things”</cite>\n      <cite>Standard distinction between physical vacua and metaphysical nothing</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"18\">\n      <learn>A hot early state is still something. Empty space in a lab is still something. The question remains: why is there anything at all?</learn>\n      <match sentence=\"Why is there something rather than nothing remains after a cosmological model.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>A model still starts with something there.</why>\n        <claimMiss>A successful model retires the metaphysical question.</claimMiss>\n        <claimMiss>“Nothing” in popular writing always means metaphysical nothing.</claimMiss>\n        <whyMiss>Laws and vacua are not somethings.</whyMiss>\n        <whyMiss>The question only applies to Tuesdays.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Models describe a world already given; a physical “vacuum” is still something.</learn>\n      <match sentence=\"Why is there something rather than nothing remains after a cosmological model.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Models describe a world already given; a physical “vacuum” is still something.</why>\n        <claimMiss>A successful model retires the metaphysical question.</claimMiss>\n        <claimMiss>“Nothing” in popular writing always means metaphysical nothing.</claimMiss>\n        <whyMiss>Laws and vacua are not somethings.</whyMiss>\n        <whyMiss>The question only applies to Tuesdays.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Fine-tuning and “why anything?” are siblings, not twins. One asks why this world’s numbers permit us; the other asks why there is a world.</learn>\n      <match sentence=\"Why is there something rather than nothing remains after a cosmological model.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold onFail=\"easy\">\n        <why>Models describe a world already given; a physical “vacuum” is still something.</why>\n        <claimMiss>A successful model retires the metaphysical question.</claimMiss>\n        <claimMiss>“Nothing” in popular writing always means metaphysical nothing.</claimMiss>\n        <whyMiss>Laws and vacua are not somethings.</whyMiss>\n        <whyMiss>The question only applies to Tuesdays.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"ob-life\" title=\"The threshold of life\" idea=\"life’s specified information is a mark of mind\">\n    <claim>Life’s specified information is a mark of mind.</claim>\n    <plain>Life’s specified information is a mark of mind.</plain>\n    <source>Abiogenesis as an open program; Genesis 1 as theology</source>\n    <loci place=\"Sky Watch\" person=\"Nora Skye\" plotId=\"observatory\" who=\"nora\" />\n    <journal title=\"Life’s open threshold\" kicker=\"Sky Watch\">\n      <body>Life’s specified information is a mark of mind. Cells require coordinated function. That is not a rumor; it is biology.</body>\n      <body>Treat the unfinished story as a place for wonder and for more work — and as a mark of mind. Do not stop the lab. Do not shrug the information away.</body>\n      <cite>Contemporary abiogenesis research as an open program</cite>\n      <cite>Genesis 1 as theological, not a lab protocol</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"19\">\n      <learn>Cells store instructions and run a coordinated life. That looks like the work of mind. Wonder is rational. So is more lab work. Do not shrug it away.</learn>\n      <match sentence=\"Life’s specified information is a mark of mind.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Cells store info that looks like a mind’s work.</why>\n        <claimMiss>A flask has already demonstrated a miracle.</claimMiss>\n        <claimMiss>Cells require no coordinated information.</claimMiss>\n        <whyMiss>The unfinished story means we should end research.</whyMiss>\n        <whyMiss>Genesis 1 is a lab protocol.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Cells store coordinated information; that looks like the work of a mind — wonder is rational, and so is more work.</learn>\n      <match sentence=\"Life’s specified information is a mark of mind.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Cells store coordinated information; that looks like the work of a mind — wonder is rational, and so is more work.</why>\n        <claimMiss>A flask has already demonstrated a miracle.</claimMiss>\n        <claimMiss>Cells require no coordinated information.</claimMiss>\n        <whyMiss>The unfinished story means we should end research.</whyMiss>\n        <whyMiss>Genesis 1 is a lab protocol.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Life’s information looks like the work of mind. Wonder is rational. So is more work. Do not trade the mark for a shrug.</learn>\n      <match sentence=\"Life’s specified information is a mark of mind.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold onFail=\"easy\">\n        <why>Cells store coordinated information; that looks like the work of a mind — wonder is rational, and so is more work.</why>\n        <claimMiss>A flask has already demonstrated a miracle.</claimMiss>\n        <claimMiss>Cells require no coordinated information.</claimMiss>\n        <whyMiss>The unfinished story means we should end research.</whyMiss>\n        <whyMiss>Genesis 1 is a lab protocol.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-stars\" title=\"Night air\" idea=\"the heavens already speak of a Maker\">\n    <claim>The heavens already speak of a Maker; fine-tuning fits that voice.</claim>\n    <plain>The heavens already speak of a Maker. Fine-tuning fits that voice.</plain>\n    <source>Psalm 19:1–4; Romans 1:20</source>\n    <loci place=\"Sky Watch\" person=\"Nora Skye\" plotId=\"observatory\" who=\"nora\" />\n    <easy points=\"10\" easyOrder=\"20\">\n      <learn>Psalm 19 and Romans 1 treat the sky as speech. The heavens already speak of a Maker.</learn>\n      <match sentence=\"The heavens already speak of a Maker; fine-tuning fits that voice.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The sky speaks of a Maker — the numbers fit that.</why>\n        <claimMiss>The heavens are silent about a Maker.</claimMiss>\n        <claimMiss>Fine-tuning contradicts the psalm.</claimMiss>\n        <whyMiss>Scripture treats the sky as decoration only.</whyMiss>\n        <whyMiss>Design inference and “the heavens declare” cannot share a grain.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Scripture treats the created order as intelligible testimony — design inference and “the heavens declare” land in the same grain.</learn>\n      <match sentence=\"The heavens already speak of a Maker; fine-tuning fits that voice.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Scripture treats the created order as intelligible testimony — design inference and “the heavens declare” land in the same grain.</why>\n        <claimMiss>The heavens are silent about a Maker.</claimMiss>\n        <claimMiss>Fine-tuning contradicts the psalm.</claimMiss>\n        <whyMiss>Scripture treats the sky as decoration only.</whyMiss>\n        <whyMiss>Design inference and “the heavens declare” cannot share a grain.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>The heavens declare the glory of God, and the sky above proclaims his handiwork.</learn>\n      <match sentence=\"The heavens already speak of a Maker; fine-tuning fits that voice.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold onFail=\"easy\">\n        <why>Scripture treats the created order as intelligible testimony — design inference and “the heavens declare” land in the same grain.</why>\n        <claimMiss>The heavens are silent about a Maker.</claimMiss>\n        <claimMiss>Fine-tuning contradicts the psalm.</claimMiss>\n        <whyMiss>Scripture treats the sky as decoration only.</whyMiss>\n        <whyMiss>Design inference and “the heavens declare” cannot share a grain.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-life\" title=\"Not cheap\" idea=\"living cells are not a cheap accident\">\n    <claim>Life, place, and mind are not cheap facts.</claim>\n    <plain>Life, place, and mind are not cheap facts.</plain>\n    <source>Acts 17:24–25</source>\n    <loci place=\"Sky Watch\" person=\"Nora Skye\" plotId=\"observatory\" who=\"nora\" />\n    <easy points=\"10\" easyOrder=\"21\">\n      <learn>Copying cells, a habitable band, and a mind that can do science all look given — the marks of a Maker.</learn>\n      <match sentence=\"Life, place, and mind are not cheap facts.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Life, a livable world, and minds look given.</why>\n        <claimMiss>Chemistry is easy to dismiss.</claimMiss>\n        <claimMiss>“It happened” is automatically the last word.</claimMiss>\n        <whyMiss>A habitable band is an unremarkable accident with no question.</whyMiss>\n        <whyMiss>Minds that do science need no home in the story.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Copying cells, a habitable band, and a mind that can do science all look given — the marks of a Maker.</learn>\n      <match sentence=\"Life, place, and mind are not cheap facts.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Copying cells, a habitable band, and a mind that can do science all look given — the marks of a Maker.</why>\n        <claimMiss>Chemistry is easy to dismiss.</claimMiss>\n        <claimMiss>“It happened” is automatically the last word.</claimMiss>\n        <whyMiss>A habitable band is an unremarkable accident with no question.</whyMiss>\n        <whyMiss>Minds that do science need no home in the story.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Acts 17:24–25: the God who made the world… gives to all mankind life and breath and everything.</learn>\n      <match sentence=\"Life, place, and mind are not cheap facts.\" place=\"Sky Watch\" person=\"Nora Skye\" />\n      <hold onFail=\"easy\">\n        <why>Copying cells, a habitable band, and a mind that can do science all look given — the marks of a Maker.</why>\n        <claimMiss>Chemistry is easy to dismiss.</claimMiss>\n        <claimMiss>“It happened” is automatically the last word.</claimMiss>\n        <whyMiss>A habitable band is an unremarkable accident with no question.</whyMiss>\n        <whyMiss>Minds that do science need no home in the story.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n</area>\n",
  "parable-hollow.xml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<area schemaVersion=\"3\" id=\"parable-hollow\" order=\"1\" title=\"Story Creek\" shortTitle=\"Creek\" subtitle=\"Jesus stories that stick\" icon=\"oak\" accent=\"#6b8f71\">\n  <blurb>The Teacher spoke in pictures — not to hide the truth, but to make it move.</blurb>\n  <intro>A creek path, oaks, and pictures you can hold: a road, a table, a lost coin in the dust.</intro>\n  <intro>Jesus taught in pictures. Play them. Then keep one true line.</intro>\n  <lesson id=\"ph-road\" title=\"The Good Samaritan\" idea=\"neighbor is the one who shows mercy\">\n    <claim>Neighbor is the one who shows mercy.</claim>\n    <plain>A neighbor is the person who shows mercy — not the person who looks like you.</plain>\n    <source>Luke 10:25–37</source>\n    <loci place=\"Story Creek\" person=\"Mercy Wren\" plotId=\"hollow\" who=\"mercy\" />\n    <journal title=\"The Teacher who taught in stories\" kicker=\"Story Creek\">\n      <body>The Gospels present Jesus as a teacher whose most characteristic form is the parable. These are not children’s decorations added to a lecture. They are the lecture — they force a decision about mercy, pride, and the identity of God.</body>\n      <body>The Good Samaritan (Luke 10:25–37) relocates the word “neighbor” from a boundary question to a mercy question. The listener is not first invited to classify others. The listener is invited to become the kind of person who crosses the road.</body>\n      <cite>Luke 10:25–37</cite>\n      <cite>Luke 10:29</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"1\">\n      <learn>Jesus tells a story. A hurt man lies on the road. Religious men walk past. A Samaritan is moved with compassion and helps. Then Jesus asks who *proved* to be a neighbor.</learn>\n      <match sentence=\"Neighbor is the one who shows mercy.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>First the hurt man, then help.</why>\n        <claimMiss>Neighbor means the person who already looks like you.</claimMiss>\n        <claimMiss>The priest is the hero because he kept the law.</claimMiss>\n        <whyMiss>The story is mainly a map of the Jericho road.</whyMiss>\n        <whyMiss>Mercy is optional once you have classified the victim.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Jesus makes the listener identify with the wounded man, then with the Samaritan moved with compassion.</learn>\n      <match sentence=\"Neighbor is the one who shows mercy.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Jesus makes the listener identify with the wounded man, then with the Samaritan moved with compassion.</why>\n        <claimMiss>Neighbor means the person who already looks like you.</claimMiss>\n        <claimMiss>The priest is the hero because he kept the law.</claimMiss>\n        <whyMiss>The story is mainly a map of the Jericho road.</whyMiss>\n        <whyMiss>Mercy is optional once you have classified the victim.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Samaritans and Judeans were divided by worship and memory (see John 4:9). Jesus flips the question (Luke 10:36): mercy proves who the neighbor is. He makes the listener identify with the wounded man — and then with costly mercy.</learn>\n      <match sentence=\"Neighbor is the one who shows mercy.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold onFail=\"easy\">\n        <why>Jesus makes the listener identify with the wounded man, then with the Samaritan moved with compassion.</why>\n        <claimMiss>Neighbor means the person who already looks like you.</claimMiss>\n        <claimMiss>The priest is the hero because he kept the law.</claimMiss>\n        <whyMiss>The story is mainly a map of the Jericho road.</whyMiss>\n        <whyMiss>Mercy is optional once you have classified the victim.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"ph-father\" title=\"The father’s run\" idea=\"the father runs before the apology is finished\">\n    <claim>The father runs with mercy before the speech is done.</claim>\n    <plain>The father runs with mercy before the son finishes his speech.</plain>\n    <source>Luke 15:11–32</source>\n    <loci place=\"Story Creek\" person=\"Mercy Wren\" plotId=\"hollow\" who=\"mercy\" />\n    <journal title=\"Mercy that runs\" kicker=\"Story Creek\">\n      <body>Luke 15 stacks three lost-and-found stories after a complaint: this man welcomes sinners and eats with them. The father’s run (Luke 15:20) is the theological center of the third story. Honor is spent so that the son can be embraced before he finishes his hired-hand speech.</body>\n      <body>The older brother shows that you can live in the house and still refuse the feast. Nearness without joy at another’s return is a second lostness.</body>\n      <cite>Luke 15:1–32</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"2\">\n      <learn>Jesus tells about a son who takes his share early and wastes it far from home. Hungry and ashamed, he starts a hired-hand speech to ask for work. But his father sees him while he is still a long way off and runs — mercy before the speech is done. He hugs the son. Honor is spent so the lost one can be welcomed; the feast is the father’s idea.</learn>\n      <match sentence=\"The father runs with mercy before the speech is done.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The father hugs him first.</why>\n        <claimMiss>The son earned the feast by writing a good apology.</claimMiss>\n        <claimMiss>The story is mainly about dividing an estate.</claimMiss>\n        <whyMiss>The father waits until justice is complete.</whyMiss>\n        <whyMiss>The older brother is the hero for staying home.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Honor is spent so the son can be embraced; the older brother shows nearness without joy.</learn>\n      <match sentence=\"The father runs with mercy before the speech is done.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Honor is spent so the son can be embraced; the older brother shows nearness without joy.</why>\n        <claimMiss>The son earned the feast by writing a good apology.</claimMiss>\n        <claimMiss>The story is mainly about dividing an estate.</claimMiss>\n        <whyMiss>The father waits until justice is complete.</whyMiss>\n        <whyMiss>The older brother is the hero for staying home.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Luke 15 stacks three lost-and-found stories. God is not only willing to receive. God seeks. The feast is the Father’s idea.</learn>\n      <match sentence=\"The father runs with mercy before the speech is done.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold onFail=\"easy\">\n        <why>Honor is spent so the son can be embraced; the older brother shows nearness without joy.</why>\n        <claimMiss>The son earned the feast by writing a good apology.</claimMiss>\n        <claimMiss>The story is mainly about dividing an estate.</claimMiss>\n        <whyMiss>The father waits until justice is complete.</whyMiss>\n        <whyMiss>The older brother is the hero for staying home.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"ph-seeds\" title=\"Pictures of the kingdom\" idea=\"the kingdom arrives in pictures, not slogans\">\n    <claim>The kingdom arrives in pictures, not slogans.</claim>\n    <plain>The kingdom comes in Jesus stories you can hold — not slogans.</plain>\n    <source>Matthew 13; Luke 15; Matthew 25</source>\n    <loci place=\"Story Creek\" person=\"Mercy Wren\" plotId=\"hollow\" who=\"mercy\" />\n    <journal title=\"Seeds, search, and a trust\" kicker=\"Story Creek\">\n      <body>Taken together, the sower, the lost sheep, the mustard seed, and the talents sketch a God who speaks, seeks, grows a kingdom from small beginnings, and will ask what was done with a trust.</body>\n      <body>That is already a case of a sort: not a syllogism, but a coherent portrait. If the portrait is true, the world is personal before it is mechanical.</body>\n      <cite>Matthew 13:1–23</cite>\n      <cite>Matthew 13:31–32</cite>\n      <cite>Luke 15:1–7</cite>\n      <cite>Matthew 25:14–30</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"3\">\n      <learn>Soil, a search, a tiny seed, and a trust. Each Jesus story asks what you will do with what you heard.</learn>\n      <match sentence=\"The kingdom arrives in pictures, not slogans.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Pictures tell it — not a slogan.</why>\n        <claimMiss>Every parable is an allegory of every detail.</claimMiss>\n        <claimMiss>The kingdom is only for people who already understand.</claimMiss>\n        <whyMiss>The sower proves every heart is the same.</whyMiss>\n        <whyMiss>The talents story is about hiding gifts until heaven.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Soil, search, a tiny seed, and a trust form a portrait — not a slogan.</learn>\n      <match sentence=\"The kingdom arrives in pictures, not slogans.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Soil, search, a tiny seed, and a trust form a portrait — not a slogan.</why>\n        <claimMiss>Every parable is an allegory of every detail.</claimMiss>\n        <claimMiss>The kingdom is only for people who already understand.</claimMiss>\n        <whyMiss>The sower proves every heart is the same.</whyMiss>\n        <whyMiss>The talents story is about hiding gifts until heaven.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Jesus’ stories assume a God who speaks, seeks, grows a kingdom, and will ask what we did with a trust. They are not proofs. They are a portrait — and a demand.</learn>\n      <match sentence=\"The kingdom arrives in pictures, not slogans.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold onFail=\"easy\">\n        <why>Soil, search, a tiny seed, and a trust form a portrait — not a slogan.</why>\n        <claimMiss>Every parable is an allegory of every detail.</claimMiss>\n        <claimMiss>The kingdom is only for people who already understand.</claimMiss>\n        <whyMiss>The sower proves every heart is the same.</whyMiss>\n        <whyMiss>The talents story is about hiding gifts until heaven.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"ph-debt\" title=\"An unpayable account\" idea=\"received mercy makes refusing mercy a contradiction\">\n    <claim>Received mercy makes refusing mercy a contradiction.</claim>\n    <plain>If you were forgiven a huge debt, you cannot choke a neighbor over a small one.</plain>\n    <source>Matthew 18:21–35</source>\n    <loci place=\"Story Creek\" person=\"Mercy Wren\" plotId=\"hollow\" who=\"mercy\" />\n    <journal title=\"The measure you use\" kicker=\"Story Creek\">\n      <body>Matthew 18:21–35 is severe because grace is severe in the opposite direction from cruelty: it creates a world. To be forgiven an unpayable debt and then throttle a neighbor is to live as if the king’s mercy never happened.</body>\n      <body>Jesus teaches his disciples to pray “forgive us our debts, as we also have forgiven our debtors” (Matt 6:12). The petition assumes the same moral grain.</body>\n      <cite>Matthew 18:21–35</cite>\n      <cite>Matthew 6:12–15</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"4\">\n      <learn>A king wipes an unpayable bill. That same servant then chokes a neighbor over a tiny sum. Example: huge debt forgiven — then a tiny one demanded.</learn>\n      <match sentence=\"Received mercy makes refusing mercy a contradiction.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>He was forgiven much, then choked a neighbor.</why>\n        <claimMiss>Forgiveness is a limited coupon on God’s spreadsheet.</claimMiss>\n        <claimMiss>Jesus is only reforming first-century banking.</claimMiss>\n        <whyMiss>Peter’s “seven times” was already the full measure.</whyMiss>\n        <whyMiss>The first servant was right to demand prison.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The servant forgiven an unpayable debt then throttles a peer over a small sum.</learn>\n      <match sentence=\"Received mercy makes refusing mercy a contradiction.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The servant forgiven an unpayable debt then throttles a peer over a small sum.</why>\n        <claimMiss>Forgiveness is a limited coupon on God’s spreadsheet.</claimMiss>\n        <claimMiss>Jesus is only reforming first-century banking.</claimMiss>\n        <whyMiss>Peter’s “seven times” was already the full measure.</whyMiss>\n        <whyMiss>The first servant was right to demand prison.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Mercy is not softness. It is the grain of God’s world — and then a question: will you live against that grain? See also Matt 6:12–15.</learn>\n      <match sentence=\"Received mercy makes refusing mercy a contradiction.\" place=\"Story Creek\" person=\"Mercy Wren\" />\n      <hold onFail=\"easy\">\n        <why>The servant forgiven an unpayable debt then throttles a peer over a small sum.</why>\n        <claimMiss>Forgiveness is a limited coupon on God’s spreadsheet.</claimMiss>\n        <claimMiss>Jesus is only reforming first-century banking.</claimMiss>\n        <whyMiss>Peter’s “seven times” was already the full measure.</whyMiss>\n        <whyMiss>The first servant was right to demand prison.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n</area>\n",
  "witness-bench.xml": "<?xml version=\"1.0\" encoding=\"UTF-8\"?>\n<area schemaVersion=\"3\" id=\"witness-bench\" order=\"2\" title=\"Witness Square\" shortTitle=\"Witness\" subtitle=\"What can we know about events we did not see?\" icon=\"scroll\" accent=\"#c4a35a\">\n  <blurb>Historians cannot rerun the past. They weigh sources, time, and motive.</blurb>\n  <intro>The old courthouse still faces the square. On the bench, the question is not “Can I feel this?” but “What kind of testimony is this, and what would a fair historian do with it?”</intro>\n  <intro>Christian faith is not only inward. It makes a public claim: Jesus of Nazareth died, was buried, and was reported alive by people who said they had seen him.</intro>\n  <intro>These challenges teach method as much as conclusion. Early, multiple, and costly testimony is not a laboratory proof — it is the kind of evidence history actually has.</intro>\n  <lesson id=\"wb-creed\" title=\"What Paul received\" idea=\"died, buried, raised, appeared — in that order\">\n    <claim>Paul hands on an early public creed: died, buried, raised, appeared.</claim>\n    <plain>Paul hands on an old shared belief: died, buried, raised, appeared.</plain>\n    <source>1 Corinthians 15:3–8</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <journal title=\"Of first importance\" kicker=\"Witness Square\">\n      <body>1 Corinthians 15:3–5 is a compressed public claim: death, burial, raising, appearances. Paul presents it as received tradition, not as a private dream. Burial resists a merely “spiritual” death; appearances resist a merely “spiritual” raising.</body>\n      <body>This is what the churches were already handing on when Paul wrote — a mid-first-century letter appealing to a still-earlier formula.</body>\n      <cite>1 Corinthians 15:3–8</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"5\">\n      <learn>This is not Paul’s private dream. He says the churches were already saying it: Christ died, was buried, was raised, and was seen.</learn>\n      <match sentence=\"Paul hands on an early public creed: died, buried, raised, appeared.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Buried and seen — not only a spirit story.</why>\n        <claimMiss>The creed is Paul’s private dream from decades later.</claimMiss>\n        <claimMiss>Paul invented the formula on the spot in Corinth.</claimMiss>\n        <whyMiss>“Buried” is only poetic decoration.</whyMiss>\n        <whyMiss>Appearances are admitted to be visions with no named people.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Burial resists a merely “spiritual” death; appearances resist a merely “spiritual” raising.</learn>\n      <match sentence=\"Paul hands on an early public creed: died, buried, raised, appeared.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Burial resists a merely “spiritual” death; appearances resist a merely “spiritual” raising.</why>\n        <claimMiss>The creed is Paul’s private dream from decades later.</claimMiss>\n        <claimMiss>Paul invented the formula on the spot in Corinth.</claimMiss>\n        <whyMiss>“Buried” is only poetic decoration.</whyMiss>\n        <whyMiss>Appearances are admitted to be visions with no named people.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Verses 6–8 widen the circle: more than five hundred, James, “all the apostles,” and last of all Paul. A creed is not a video. It is a public, early summary of what the churches were already saying.</learn>\n      <match sentence=\"Paul hands on an early public creed: died, buried, raised, appeared.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>Burial resists a merely “spiritual” death; appearances resist a merely “spiritual” raising.</why>\n        <claimMiss>The creed is Paul’s private dream from decades later.</claimMiss>\n        <claimMiss>Paul invented the formula on the spot in Corinth.</claimMiss>\n        <whyMiss>“Buried” is only poetic decoration.</whyMiss>\n        <whyMiss>Appearances are admitted to be visions with no named people.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"wb-early\" title=\"Why historians call it early\" idea=\"the creed is early testimony, not a medieval insert\">\n    <claim>The resurrection claim sits close to the events, not as a late legend.</claim>\n    <plain>That old shared belief is early testimony, not a medieval insert.</plain>\n    <source>1 Corinthians 15:3–7; Luke 1:1–4</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <journal title=\"Early is not the same as easy\" kicker=\"Witness Square\">\n      <body>Historians cannot rewind the world. They ask how close a report stands to the events, how formulaic it is, and whether the author is appealing to known people (Cephas, the Twelve, James, a large group, Paul himself).</body>\n      <body>Luke 1:1–4 shows another first-century Christian writer claiming the posture of inquiry among eyewitnesses. That posture can be tested. It stands to be weighed.</body>\n      <cite>1 Corinthians 15:3–7</cite>\n      <cite>Luke 1:1–4</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"6\">\n      <learn>Paul wrote in the mid-first century. He says he received this core and passed it on. That is close to the events — not a monk’s later add-on.</learn>\n      <match sentence=\"The resurrection claim sits close to the events, not as a late legend.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Paul names known people who saw it.</why>\n        <claimMiss>Early is the same as laboratory proof.</claimMiss>\n        <claimMiss>No first-century writer claims to have asked witnesses.</claimMiss>\n        <whyMiss>Named people make a report less testable.</whyMiss>\n        <whyMiss>Distance in time is the only historical question that matters.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Paul quotes a received formula and names known people; Luke claims inquiry among witnesses.</learn>\n      <match sentence=\"The resurrection claim sits close to the events, not as a late legend.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Paul quotes a received formula and names known people; Luke claims inquiry among witnesses.</why>\n        <claimMiss>Early is the same as laboratory proof.</claimMiss>\n        <claimMiss>No first-century writer claims to have asked witnesses.</claimMiss>\n        <whyMiss>Named people make a report less testable.</whyMiss>\n        <whyMiss>Distance in time is the only historical question that matters.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Compare Luke 1:1–4: a first-century writer claiming inquiry among eyewitnesses. That posture can be tested. It stands to be weighed.</learn>\n      <match sentence=\"The resurrection claim sits close to the events, not as a late legend.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>Paul quotes a received formula and names known people; Luke claims inquiry among witnesses.</why>\n        <claimMiss>Early is the same as laboratory proof.</claimMiss>\n        <claimMiss>No first-century writer claims to have asked witnesses.</claimMiss>\n        <whyMiss>Named people make a report less testable.</whyMiss>\n        <whyMiss>Distance in time is the only historical question that matters.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"wb-method\" title=\"Tools of the ancient historian\" idea=\"historians weigh sources; they cannot rerun the past\">\n    <claim>Ordinary historical tools weigh testimony; they do not replace reading.</claim>\n    <plain>Historians weigh sources. They cannot rerun the past.</plain>\n    <source>Standard historical method</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <journal title=\"How the past is weighed\" kicker=\"Witness Square\">\n      <body>Multiple attestation, embarrassment, early testimony, and contextual credibility are ordinary tools. They do not replace reading. They resist the story that every Christian report is a late pious novel.</body>\n      <body>Used honestly, they also resist the opposite laziness: “an early creed is already a laboratory proof.” History gives testimony, not a rerun.</body>\n      <cite>Standard historical method as used in ancient history and historical Jesus studies</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"7\">\n      <learn>Ask: how many reports? How awkward is the detail? How soon was it said? Does it fit that world? Those tools test a report. They are not a chemistry lab.</learn>\n      <match sentence=\"Ordinary historical tools weigh testimony; they do not replace reading.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Many early, awkward reports beat a late tale.</why>\n        <claimMiss>An early creed is already a laboratory proof.</claimMiss>\n        <claimMiss>Every Christian report is automatically a late novel.</claimMiss>\n        <whyMiss>Method is a way to skip the texts themselves.</whyMiss>\n        <whyMiss>Embarrassment means a story must be false.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Multiple attestation, embarrassment, early reports, and context resist “late pious novel.”</learn>\n      <match sentence=\"Ordinary historical tools weigh testimony; they do not replace reading.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Multiple attestation, embarrassment, early reports, and context resist “late pious novel.”</why>\n        <claimMiss>An early creed is already a laboratory proof.</claimMiss>\n        <claimMiss>Every Christian report is automatically a late novel.</claimMiss>\n        <whyMiss>Method is a way to skip the texts themselves.</whyMiss>\n        <whyMiss>Embarrassment means a story must be false.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>These criteria can be overused. They do not replace reading texts as wholes. They do resist a lazy story: “Someone, somewhere, made everything up much later.”</learn>\n      <match sentence=\"Ordinary historical tools weigh testimony; they do not replace reading.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>Multiple attestation, embarrassment, early reports, and context resist “late pious novel.”</why>\n        <claimMiss>An early creed is already a laboratory proof.</claimMiss>\n        <claimMiss>Every Christian report is automatically a late novel.</claimMiss>\n        <whyMiss>Method is a way to skip the texts themselves.</whyMiss>\n        <whyMiss>Embarrassment means a story must be false.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"wb-women\" title=\"Idle talk\" idea=\"women as first witnesses is an awkward detail to invent\">\n    <claim>The first tomb reports begin with women — an awkward opening if invented for respectability.</claim>\n    <plain>Women as first witnesses is an awkward detail to invent.</plain>\n    <source>Luke 24:1–11</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <journal title=\"Awkward beginnings\" kicker=\"Witness Square\">\n      <body>The tomb stories begin with women, and Luke records that the apostles dismissed them (Luke 24:11). That is an odd opening if the only goal is later public respectability.</body>\n      <body>Outside the Gospels, Tacitus (Annals 15.44) notes Christus executed under Pilate and a movement that spread to Rome. Josephus (Antiquities 18.63–64) is partly disputed because of later Christian touches, and honesty about that dispute belongs in the dossier.</body>\n      <cite>Mark 16:1–8</cite>\n      <cite>Luke 24:1–11</cite>\n      <cite>John 20:1–18</cite>\n      <cite>Tacitus, Annals 15.44</cite>\n      <cite>Josephus, Antiquities 18.63–64</cite>\n    </journal>\n    <easy points=\"10\" easyOrder=\"8\">\n      <learn>The tomb stories begin with women. Luke says the men called it idle talk. If you only wanted later respect, you would more likely lead with respected men.</learn>\n      <match sentence=\"The first tomb reports begin with women — an awkward opening if invented for respectability.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The men first called the women wrong.</why>\n        <claimMiss>The Gospels open with the Roman senate converting overnight.</claimMiss>\n        <claimMiss>Women were the most legally impressive public witnesses.</claimMiss>\n        <whyMiss>Luke sands away any dismissal of the first report.</whyMiss>\n        <whyMiss>Outside writers never mention Christus or Pilate.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Luke records that the apostles dismissed them — a costly opening if the goal were instant respectability.</learn>\n      <match sentence=\"The first tomb reports begin with women — an awkward opening if invented for respectability.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Luke records that the apostles dismissed them — a costly opening if the goal were instant respectability.</why>\n        <claimMiss>The Gospels open with the Roman senate converting overnight.</claimMiss>\n        <claimMiss>Women were the most legally impressive public witnesses.</claimMiss>\n        <whyMiss>Luke sands away any dismissal of the first report.</whyMiss>\n        <whyMiss>Outside writers never mention Christus or Pilate.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Josephus, Antiquities 18.63–64, is partly disputed because of later Christian touches. Honesty about that dispute belongs in the dossier.</learn>\n      <match sentence=\"The first tomb reports begin with women — an awkward opening if invented for respectability.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>Luke records that the apostles dismissed them — a costly opening if the goal were instant respectability.</why>\n        <claimMiss>The Gospels open with the Roman senate converting overnight.</claimMiss>\n        <claimMiss>Women were the most legally impressive public witnesses.</claimMiss>\n        <whyMiss>Luke sands away any dismissal of the first report.</whyMiss>\n        <whyMiss>Outside writers never mention Christus or Pilate.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-names\" title=\"Names that stay\" idea=\"the resurrection claim rests on named witnesses\">\n    <claim>The resurrection claim stacks named witnesses, not one private voice.</claim>\n    <plain>The resurrection claim stacks named witnesses, not one private voice.</plain>\n    <source>1 Corinthians 15:5–6</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <easy points=\"10\" easyOrder=\"9\">\n      <learn>Paul lists Cephas, the Twelve, and more than five hundred — many still living then.</learn>\n      <match sentence=\"The resurrection claim stacks named witnesses, not one private voice.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>Paul names many people who were still alive.</why>\n        <claimMiss>Paul refuses to name anyone.</claimMiss>\n        <claimMiss>Only one anonymous dreamer is cited.</claimMiss>\n        <whyMiss>A crowd appearance would have been hidden.</whyMiss>\n        <whyMiss>Cephas is left off the list.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>Paul lists Cephas, the Twelve, and more than five hundred — many still living then.</learn>\n      <match sentence=\"The resurrection claim stacks named witnesses, not one private voice.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>Paul lists Cephas, the Twelve, and more than five hundred — many still living then.</why>\n        <claimMiss>Paul refuses to name anyone.</claimMiss>\n        <claimMiss>Only one anonymous dreamer is cited.</claimMiss>\n        <whyMiss>A crowd appearance would have been hidden.</whyMiss>\n        <whyMiss>Cephas is left off the list.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>He appeared to Cephas, then to the twelve. Then he appeared to more than five hundred brothers at one time.</learn>\n      <match sentence=\"The resurrection claim stacks named witnesses, not one private voice.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>Paul lists Cephas, the Twelve, and more than five hundred — many still living then.</why>\n        <claimMiss>Paul refuses to name anyone.</claimMiss>\n        <claimMiss>Only one anonymous dreamer is cited.</claimMiss>\n        <whyMiss>A crowd appearance would have been hidden.</whyMiss>\n        <whyMiss>Cephas is left off the list.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-creed\" title=\"Older than the letter\" idea=\"the first church already said he died, was buried, and was raised\">\n    <claim>The creed sits between the event and Paul’s letter.</claim>\n    <plain>The old shared belief sits between the event and Paul’s letter.</plain>\n    <source>1 Corinthians 15:3–4</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <easy points=\"10\" easyOrder=\"10\">\n      <learn>If that short line is early, the claim is close to what it names: died, buried, raised.</learn>\n      <match sentence=\"The creed sits between the event and Paul’s letter.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>If the line is early, it is close to the event.</why>\n        <claimMiss>Paul invents the creed as he writes.</claimMiss>\n        <claimMiss>Burial is skipped because it does not matter.</claimMiss>\n        <whyMiss>The letter is older than any tradition it quotes.</whyMiss>\n        <whyMiss>Nothing was handed on; it was only felt.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>If the formula is early, the claim is close to what it names: died, buried, raised.</learn>\n      <match sentence=\"The creed sits between the event and Paul’s letter.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>If the formula is early, the claim is close to what it names: died, buried, raised.</why>\n        <claimMiss>Paul invents the creed as he writes.</claimMiss>\n        <claimMiss>Burial is skipped because it does not matter.</claimMiss>\n        <whyMiss>The letter is older than any tradition it quotes.</whyMiss>\n        <whyMiss>Nothing was handed on; it was only felt.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>Christ died… he was buried… he was raised on the third day. Burial and raising are both named.</learn>\n      <match sentence=\"The creed sits between the event and Paul’s letter.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>If the formula is early, the claim is close to what it names: died, buried, raised.</why>\n        <claimMiss>Paul invents the creed as he writes.</claimMiss>\n        <claimMiss>Burial is skipped because it does not matter.</claimMiss>\n        <whyMiss>The letter is older than any tradition it quotes.</whyMiss>\n        <whyMiss>Nothing was handed on; it was only felt.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n  <lesson id=\"daily-empty\" title=\"Morning\" idea=\"the first Easter reports are awkward on purpose\">\n    <claim>The first Easter reports include an empty place, women, fear, and wonder.</claim>\n    <plain>The first Easter reports include an empty place, women, fear, and wonder.</plain>\n    <source>Luke 24:2–3</source>\n    <loci place=\"Witness Square\" person=\"Silas Whitman\" plotId=\"bench\" who=\"silas\" />\n    <easy points=\"10\" easyOrder=\"11\">\n      <learn>The town does not sand that awkwardness into a tidy triumph.</learn>\n      <match sentence=\"The first Easter reports include an empty place, women, fear, and wonder.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"medium\" onFail=\"easy\">\n        <why>The first report stays awkward — not a tidy win.</why>\n        <claimMiss>Rome instantly converts the senate.</claimMiss>\n        <claimMiss>Women are absent from the first reports.</claimMiss>\n        <whyMiss>The tomb is found occupied and explained.</whyMiss>\n        <whyMiss>Fear is edited out of the opening.</whyMiss>\n      </hold>\n    </easy>\n    <medium points=\"12\">\n      <learn>The town does not sand that awkwardness into a tidy triumph.</learn>\n      <match sentence=\"The first Easter reports include an empty place, women, fear, and wonder.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold levelUpTo=\"hard\" onFail=\"easy\">\n        <why>The town does not sand that awkwardness into a tidy triumph.</why>\n        <claimMiss>Rome instantly converts the senate.</claimMiss>\n        <claimMiss>Women are absent from the first reports.</claimMiss>\n        <whyMiss>The tomb is found occupied and explained.</whyMiss>\n        <whyMiss>Fear is edited out of the opening.</whyMiss>\n      </hold>\n    </medium>\n    <hard points=\"15\">\n      <learn>They found the stone rolled away from the tomb, but when they went in they did not find the body.</learn>\n      <match sentence=\"The first Easter reports include an empty place, women, fear, and wonder.\" place=\"Witness Square\" person=\"Silas Whitman\" />\n      <hold onFail=\"easy\">\n        <why>The town does not sand that awkwardness into a tidy triumph.</why>\n        <claimMiss>Rome instantly converts the senate.</claimMiss>\n        <claimMiss>Women are absent from the first reports.</claimMiss>\n        <whyMiss>The tomb is found occupied and explained.</whyMiss>\n        <whyMiss>Fear is edited out of the opening.</whyMiss>\n      </hold>\n    </hard>\n  </lesson>\n</area>\n",
}
